import asyncio
import hashlib
import hmac
import secrets
import time
import json
import base64
from dataclasses import dataclass, field
from typing import Dict, Optional, Tuple
from aiohttp import web, ClientSession
import aiohttp


@dataclass
class AuthSession:
    user_id: str
    state: str
    nonce: str
    code_verifier: str
    redirect_uri: str
    created_at: float = field(default_factory=time.time)


class TokenVerifier:
    def __init__(self, signing_key: bytes):
        self.signing_key = signing_key

    def create_session_token(self, user_id: str, session_id: str) -> str:
        payload = json.dumps({
            "sub": user_id,
            "sid": session_id,
            "iat": int(time.time()),
            "exp": int(time.time()) + 3600
        })
        payload_b64 = base64.urlsafe_b64encode(payload.encode()).decode().rstrip('=')
        sig = hmac.new(self.signing_key, payload_b64.encode(), hashlib.sha256).hexdigest()
        return f"{payload_b64}.{sig}"

    def verify_session_token(self, token: str) -> Optional[dict]:
        try:
            parts = token.split('.')
            if len(parts) != 2:
                return None
            payload_b64, sig = parts
            expected_sig = hmac.new(self.signing_key, payload_b64.encode(), hashlib.sha256).hexdigest()
            # Constant-time comparison for signature
            if not hmac.compare_digest(sig, expected_sig):
                return None
            padding = 4 - len(payload_b64) % 4
            payload_b64 += '=' * padding
            payload = json.loads(base64.urlsafe_b64decode(payload_b64))
            if payload.get('exp', 0) < time.time():
                return None
            return payload
        except Exception:
            return None


class OAuthFlowManager:
    def __init__(self, config: dict):
        self.config = config
        self.pending_flows: Dict[str, AuthSession] = {}
        self.flow_lock = asyncio.Lock()
        self.token_verifier = TokenVerifier(config['signing_key'].encode())
        self._cleanup_task = None

    async def start_cleanup(self):
        self._cleanup_task = asyncio.create_task(self._periodic_cleanup())

    async def _periodic_cleanup(self):
        while True:
            await asyncio.sleep(60)
            async with self.flow_lock:
                now = time.time()
                expired = [k for k, v in self.pending_flows.items() 
                          if now - v.created_at > 600]
                for k in expired:
                    del self.pending_flows[k]

    def _generate_pkce(self) -> Tuple[str, str]:
        verifier = secrets.token_urlsafe(32)
        challenge = base64.urlsafe_b64encode(
            hashlib.sha256(verifier.encode()).digest()
        ).decode().rstrip('=')
        return verifier, challenge

    async def initiate_flow(self, user_id: str, redirect_uri: str) -> str:
        state = secrets.token_urlsafe(32)
        nonce = secrets.token_urlsafe(16)
        code_verifier, code_challenge = self._generate_pkce()

        session = AuthSession(
            user_id=user_id,
            state=state,
            nonce=nonce,
            code_verifier=code_verifier,
            redirect_uri=redirect_uri
        )

        async with self.flow_lock:
            self.pending_flows[state] = session

        auth_url = (
            f"{self.config['authorization_endpoint']}?"
            f"response_type=code&"
            f"client_id={self.config['client_id']}&"
            f"redirect_uri={redirect_uri}&"
            f"state={state}&"
            f"nonce={nonce}&"
            f"code_challenge={code_challenge}&"
            f"code_challenge_method=S256&"
            f"scope=openid+profile+email"
        )
        return auth_url

    async def complete_flow(self, state: str, code: str) -> Optional[dict]:
        # Atomically retrieve AND remove the pending flow
        async with self.flow_lock:
            session = self.pending_flows.pop(state, None)

        if session is None:
            return None

        # Check expiration
        if time.time() - session.created_at > 600:
            return None

        # Exchange code for tokens
        token_response = await self._exchange_code(
            code=code,
            redirect_uri=session.redirect_uri,
            code_verifier=session.code_verifier
        )

        if token_response is None:
            return None

        # Validate the ID token nonce
        id_token_claims = self._parse_id_token(token_response.get('id_token', ''))
        if id_token_claims is not None:
            received_nonce = id_token_claims.get('nonce', '')
            # Constant-time comparison to avoid timing side-channel on the nonce
            if not hmac.compare_digest(
                str(received_nonce).encode(), session.nonce.encode()
            ):
                return None

        # Create application session
        session_id = secrets.token_urlsafe(16)
        app_token = self.token_verifier.create_session_token(
            session.user_id, session_id
        )

        return {
            'token': app_token,
            'user_id': session.user_id,
            'id_token_claims': id_token_claims
        }

    async def _exchange_code(self, code: str, redirect_uri: str, code_verifier: str) -> Optional[dict]:
        try:
            async with ClientSession() as http:
                resp = await http.post(
                    self.config['token_endpoint'],
                    data={
                        'grant_type': 'authorization_code',
                        'code': code,
                        'redirect_uri': redirect_uri,
                        'client_id': self.config['client_id'],
                        'client_secret': self.config['client_secret'],
                        'code_verifier': code_verifier
                    },
                    timeout=aiohttp.ClientTimeout(total=10)
                )
                if resp.status == 200:
                    return await resp.json()
                return None
        except Exception:
            return None

    def _parse_id_token(self, token: str) -> Optional[dict]:
        try:
            parts = token.split('.')
            if len(parts) != 3:
                return None
            payload = parts[1]
            padding = 4 - len(payload) % 4
            payload += '=' * padding
            return json.loads(base64.urlsafe_b64decode(payload))
        except Exception:
            return None


class SecureRedirectValidator:
    ALLOWED_DOMAINS = ['app.internal.corp', 'dashboard.internal.corp']
    ALLOWED_PATHS = ['/callback', '/auth/callback', '/oauth/complete']

    @classmethod
    def validate(cls, redirect_uri: str) -> bool:
        if not redirect_uri or len(redirect_uri) > 2048:
            return False
        try:
            from urllib.parse import urlparse
            parsed = urlparse(redirect_uri)
        except Exception:
            return False

        if parsed.scheme != 'https':
            return False
        if parsed.fragment:
            return False
        if '@' in (parsed.netloc or ''):
            return False
        if not parsed.hostname:
            return False

        hostname = parsed.hostname.lower().rstrip('.')

        # Reject any percent-encoding in hostname
        if '%' in hostname:
            return False

        # Strict domain match
        if hostname not in cls.ALLOWED_DOMAINS:
            return False

        # Path validation
        path = parsed.path.rstrip('/')
        if path not in cls.ALLOWED_PATHS:
            return False

        return True


async def handle_login(request: web.Request) -> web.Response:
    """Initiates OAuth flow for authenticated users."""
    # Verify existing session
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return web.json_response({'error': 'unauthorized'}, status=401)

    flow_mgr: OAuthFlowManager = request.app['flow_manager']
    claims = flow_mgr.token_verifier.verify_session_token(auth_header[7:])
    if claims is None:
        return web.json_response({'error': 'invalid_token'}, status=401)

    redirect_uri = request.query.get('redirect_uri', '')
    if not SecureRedirectValidator.validate(redirect_uri):
        return web.json_response({'error': 'invalid_redirect_uri'}, status=400)

    auth_url = await flow_mgr.initiate_flow(claims['sub'], redirect_uri)
    return web.json_response({'authorization_url': auth_url})


async def handle_callback(request: web.Request) -> web.Response:
    """Handles OAuth callback - exchanges code for tokens."""
    state = request.query.get('state', '')
    code = request.query.get('code', '')
    error = request.query.get('error', '')

    if error:
        return web.json_response({'error': error}, status=400)

    if not state or not code:
        return web.json_response({'error': 'missing_params'}, status=400)

    flow_mgr: OAuthFlowManager = request.app['flow_manager']
    result = await flow_mgr.complete_flow(state, code)

    if result is None:
        return web.json_response({'error': 'flow_failed'}, status=400)

    return web.json_response({
        'session_token': result['token'],
        'user_id': result['user_id']
    })


async def create_app() -> web.Application:
    app = web.Application()

    config = {
        'client_id': 'app-client-id',
        'client_secret': 'super-secret-client-secret',
        'authorization_endpoint': 'https://idp.internal.corp/authorize',
        'token_endpoint': 'https://idp.internal.corp/token',
        'signing_key': secrets.token_hex(32)
    }

    flow_mgr = OAuthFlowManager(config)
    app['flow_manager'] = flow_mgr

    app.router.add_get('/auth/login', handle_login)
    app.router.add_get('/auth/callback', handle_callback)

    app.on_startup.append(lambda _: flow_mgr.start_cleanup())

    return app


if __name__ == '__main__':
    web.run_app(create_app(), host='127.0.0.1', port=8080)
